#include <iostream>
#include <cstdio>
#include <cstring>
#include <string>
#include <algorithm>
#include <queue>
#include <map>
#include <set>
#include <cstdlib>
using namespace std;

const int MAXN = 200;
const int MAXM = 100000;
const int INF = 199999999;

int board[20][20];
int adj[MAXN][MAXN];
int n, N, limit;
string input;
int human[MAXN][3];
int robot[MAXN][3];
int zr, zc;
int hcnt, rcnt;
int moves[4][2] = {{0,-1},{0,1},{-1,0},{1,0}};

int valid(int r, int c) {
    if (r > 0 && r <= n && c > 0 && c <= n && board[r][c] != -1)
        return (r-1)*n + c;
    return -1;
}

void makeGraph() {
    N = n * n;
    memset(adj, -1, sizeof(adj));
    for (int r = 1; r <= n; ++r) {
        for (int c = 1; c <= n; ++c) {
            if (board[r][c] == -1) continue;
            int p = (r-1)*n + c;
            adj[p][p] = 0;
            for (int d = 0; d < 4; ++d) {
                int nr = r + moves[d][0];
                int nc = c + moves[d][1];
                if (nr > 0 && nr <= n && nc > 0 && nc <= n && board[nr][nc] != -1) {
                    int np = (nr-1)*n + nc;
                    adj[p][np] = 1;
                }
            }
        }
    }
}

int dist[MAXN];
int q[MAXM];
int inq[MAXN];

void spfa() {
    int front = 0, rear = 1;
    for (int i = 1; i <= N; ++i) dist[i] = INF;
    int start = (zr-1)*n + zc;
    dist[start] = 0;
    q[0] = start;
    while (front < rear) {
        int u = q[front++];
        for (int v = 1; v <= N; ++v) {
            if (adj[u][v] == 1 && dist[v] > dist[u] + 1) {
                dist[v] = dist[u] + 1;
                q[rear++] = v;
            }
        }
    }
}

void floyd() {
    for (int k = 1; k <= N; ++k) {
        for (int i = 1; i <= N; ++i) {
            if (adj[i][k] == -1) continue;
            for (int j = 1; j <= N; ++j) {
                if (adj[k][j] == -1) continue;
                if (adj[i][j] == -1 || adj[i][j] > adj[i][k] + adj[k][j])
                    adj[i][j] = adj[i][k] + adj[k][j];
            }
        }
    }
}

struct Edge {
    int st, ed, flow, next;
} edge[MAXM];
int head[MAXN];
int E;
int src, dest;

void addEdge(int st, int ed, int flow) {
    edge[E].st = st; edge[E].ed = ed; edge[E].flow = flow; edge[E].next = head[st];
    head[st] = E++;
    edge[E].st = ed; edge[E].ed = st; edge[E].flow = 0; edge[E].next = head[ed];
    head[ed] = E++;
}

void buildFlow() {
    memset(head, -1, sizeof(head));
    E = 0;
    src = 0;
    dest = hcnt + rcnt + 1;
    for (int i = 1; i <= hcnt; ++i)
        addEdge(src, i, human[i][2]);
    for (int i = 1; i <= rcnt; ++i)
        addEdge(hcnt + i, dest, robot[i][2]);
    for (int i = 1; i <= hcnt; ++i) {
        for (int j = 1; j <= rcnt; ++j) {
            int p1 = (human[i][0]-1)*n + human[i][1];
            int p2 = (robot[j][0]-1)*n + robot[j][1];
            if (adj[p1][p2] != -1 && adj[p1][p2] <= limit && adj[p1][p2] < dist[p2]) {
                addEdge(i, hcnt + j, INF);
            } else if (adj[p1][p2] != -1 && adj[p1][p2] <= limit && adj[p1][p2] == dist[p2]) {
                for (int d = 0; d < 4; ++d) {
                    int rr = robot[j][0] + moves[d][0];
                    int cc = robot[j][1] + moves[d][1];
                    int pp = valid(rr, cc);
                    if (pp != -1) {
                        if (adj[p1][pp] == adj[p1][p2] - 1 && adj[p1][pp] < dist[pp]) {
                            addEdge(i, hcnt + j, INF);
                        }
                    }
                }
            }
        }
    }
}

int d[MAXN];
bool bfs() {
    int que[MAXN];
    int front = 0, rear = 1;
    que[0] = src;
    memset(d, -1, sizeof(d));
    d[src] = 0;
    while (front < rear) {
        int u = que[front++];
        for (int i = head[u]; i != -1; i = edge[i].next) {
            int v = edge[i].ed;
            if (d[v] == -1 && edge[i].flow > 0) {
                d[v] = d[u] + 1;
                if (v == dest) return true;
                que[rear++] = v;
            }
        }
    }
    return false;
}

int stk[MAXN];
int cur[MAXN];

int dinic() {
    int ret = 0;
    while (bfs()) {
        int u = src, tail = 0;
        for (int i = src; i <= dest; ++i) cur[i] = head[i];
        while (cur[src] != -1) {
            if (u != dest && cur[u] != -1 && edge[cur[u]].flow > 0 && d[u] != -1 && d[u] + 1 == d[edge[cur[u]].ed]) {
                stk[tail++] = cur[u];
                u = edge[cur[u]].ed;
            } else if (u == dest) {
                int minf = INF;
                for (int i = tail - 1; i >= 0; --i)
                    if (edge[stk[i]].flow < minf) minf = edge[stk[i]].flow;
                ret += minf;
                for (int i = tail - 1; i >= 0; --i) {
                    edge[stk[i]].flow -= minf;
                    edge[stk[i]^1].flow += minf;
                    if (edge[stk[i]].flow == 0) tail = i;
                }
                u = edge[stk[tail]].st;
            } else {
                while (tail > 0 && u != src && cur[u] == -1)
                    u = edge[stk[--tail]].st;
                cur[u] = edge[cur[u]].next;
            }
        }
    }
    return ret;
}

int solve() {
    board[zr][zc] = 0;
    makeGraph();
    spfa();
    board[zr][zc] = -1;
    makeGraph();
    floyd();
    buildFlow();
    return dinic();
}

int main() {
    cin >> n >> limit;
    hcnt = rcnt = 0;
    memset(board, 0, sizeof(board));
    for (int i = 1; i <= n; ++i) {
        cin >> input;
        for (int j = 0; j < n; ++j) {
            if (input[j] == 'Y') board[i][j+1] = -1;
            else if (input[j] == 'Z') {
                zr = i; zc = j+1;
                board[i][j+1] = -1;
            } else if (input[j] > '0' && input[j] <= '9') {
                human[++hcnt][0] = i;
                human[hcnt][1] = j+1;
                human[hcnt][2] = input[j] - '0';
            }
        }
    }
    for (int i = 1; i <= n; ++i) {
        cin >> input;
        for (int j = 0; j < n; ++j) {
            if (input[j] > '0' && input[j] <= '9') {
                robot[++rcnt][0] = i;
                robot[rcnt][1] = j+1;
                robot[rcnt][2] = input[j] - '0';
            }
        }
    }
    cout << solve() << endl;
    return 0;
}
